import {markResultStale} from '../form-behavior.mjs';
import {field,e,error,download} from '../ui.mjs';
// Small, explicit local-save table editor shared by the manual planning tools.
export function recordForm(mount,{columns,initial,fields=[],run,label='Update results',note='',saveKey,auto=true}){
 let data=initial.map(r=>({...r})),saving=false,disposed=false;const defaults=Object.fromEntries(columns.map(c=>[c.id,c.value??(c.type==='number'?0:'')]));
 mount.innerHTML='<h2>Make a little room for the details.</h2><form><div class="form-grid">'+fields.map(field).join('')+'</div><div class="record-editor"></div><button type="button" class="btn secondary small" data-add-row>+ Add row</button><div class="form-actions"><button type="submit" class="btn primary">'+e(label)+'</button></div><div class="form-error"></div><div class="record-status" data-record-status role="status" hidden></div></form><p class="form-note">'+e(note)+'</p>'+(saveKey?'<label class="save-choice"><input type="checkbox" data-local-save> Save on this device</label><div class="record-backups"><button type="button" class="btn secondary small" data-export-json>Export backup JSON</button><button type="button" class="btn secondary small" data-import-json>Import backup JSON</button><input type="file" accept="application/json,.json" hidden data-import-file></div>':'');
 const f=mount.querySelector('form'),editor=mount.querySelector('.record-editor'),submit=f.querySelector('[type=submit]');
 const settings=()=>Object.fromEntries(fields.map(c=>[c.id,f.elements[c.id]?.value||'']));
 function read(){data=[...editor.querySelectorAll('tbody tr')].map(row=>Object.fromEntries(columns.map(c=>[c.id,row.querySelector('[data-column="'+c.id+'"]').value])));return data;}
 function persist(){if(!saveKey||!saving)return;try{localStorage.setItem(saveKey,JSON.stringify({rows:read(),settings:settings()}));}catch{error(f.querySelector('.form-error'),'Local saving is unavailable. Export a backup to keep your entries.');}}
 function restore(payload){if(!Array.isArray(payload?.rows)||payload.rows.length<1||payload.rows.length>300)throw Error('Use a valid backup with 1–300 rows.');data=payload.rows.map(row=>Object.fromEntries(columns.map(c=>{const value=row[c.id]??defaults[c.id];if(!['string','number'].includes(typeof value)||String(value).length>5000)throw Error('The backup contains an unsupported value.');return [c.id,value];})));for(const c of fields)if(payload.settings?.[c.id]!==undefined)f.elements[c.id].value=String(payload.settings[c.id]);draw();}
 function draw(){editor.innerHTML='<table class="record-table"><thead><tr>'+columns.map(c=>'<th scope="col">'+e(c.label)+'</th>').join('')+'<th scope="col">Action</th></tr></thead><tbody>'+data.map((row,i)=>'<tr>'+columns.map(c=>'<td data-label="'+e(c.label)+'">'+(c.options?'<select data-column="'+c.id+'" aria-label="'+e(c.label+', row '+(i+1))+'">'+c.options.map(o=>{const [value,name]=Array.isArray(o)?o:[o,o];return '<option value="'+e(value)+'" '+(String(value)===String(row[c.id])?'selected':'')+'>'+e(name)+'</option>';}).join('')+'</select>':'<input data-column="'+c.id+'" aria-label="'+e(c.label+', row '+(i+1))+'" type="'+(c.type||'text')+'" value="'+e(row[c.id]??defaults[c.id])+'" '+(c.required===false?'':'required')+' '+(c.min!==undefined?'min="'+c.min+'"':'')+' '+(c.max!==undefined?'max="'+c.max+'"':'')+' step="'+(c.step||'any')+'" maxlength="5000">')+'</td>').join('')+'<td data-label="Action"><button type="button" class="record-remove" data-remove-row="'+i+'" aria-label="Remove row '+(i+1)+'">Remove</button></td></tr>').join('')+'</tbody></table>';}
 if(saveKey){try{const stored=localStorage.getItem(saveKey);if(stored){restore(JSON.parse(stored));saving=true;mount.querySelector('[data-local-save]').checked=true;}}catch{}mount.querySelector('[data-local-save]').onchange=ev=>{saving=ev.target.checked;if(saving)persist();else try{localStorage.removeItem(saveKey);}catch{}};mount.querySelector('[data-export-json]').onclick=()=>download(new Blob([JSON.stringify({rows:read(),settings:settings()},null,2)],{type:'application/json'}),'nepocore-table-backup.json');const input=mount.querySelector('[data-import-file]');mount.querySelector('[data-import-json]').onclick=()=>{input.value='';input.click();};input.onchange=async()=>{try{if(!input.files[0])return;if(input.files[0].size>2*1024*1024)throw Error('Use a JSON backup under 2 MB.');const parsed=JSON.parse(await input.files[0].text());if(disposed)return;restore(parsed);f.requestSubmit();}catch(ex){if(!disposed)error(f.querySelector('.form-error'),ex.message);}};}
 draw();editor.onclick=ev=>{const button=ev.target.closest('[data-remove-row]');if(!button)return;read();if(data.length===1){data=[{...defaults}];}else data.splice(+button.dataset.removeRow,1);draw();persist();};mount.querySelector('[data-add-row]').onclick=()=>{read();if(data.length>=300)return;data.push({...defaults});draw();};f.onsubmit=async ev=>{ev?.preventDefault();if(!f.reportValidity())return;submit.disabled=true;f.querySelector('.form-error').innerHTML='';try{const revision=mount.dataset.inputRevision;await run(read(),settings(),{updateRows:rows=>{data=rows.map(r=>({...r}));draw();},submit:()=>f.requestSubmit()});if(mount.dataset.inputRevision!==revision)markResultStale(document.querySelector('#tool-result'));const status=f.querySelector('[data-record-status]');status.hidden=false;status.innerHTML='<span>Results updated.</span><button type="button" class="btn secondary small">View results ↓</button>';status.querySelector('button').onclick=()=>{const out=document.querySelector('#tool-result');out?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});};persist();}catch(ex){if(!disposed)error(f.querySelector('.form-error'),ex.message);}finally{if(!disposed)submit.disabled=false;}};if(auto)f.requestSubmit();return()=>{persist();disposed=true;};
}
